562→// preTaskFilePrefix is the prefix for pre-task state files
563→const preTaskFilePrefix = "pre-task-"
564→
565→// FindActivePreTaskFile finds an active pre-task file in .entire/tmp/ and returns
566→// the parent Task's tool_use_id. Returns ("", false) if no pre-task file exists.
567→// When multiple pre-task files exist (nested subagents), returns the most recently
568→// modified one.
569→// Works correctly from any subdirectory within the repository.
570→func FindActivePreTaskFile(ctx context.Context) (taskToolUseID string, found bool) {
571→	tmpDirAbs := resolveTmpDir(ctx)
572→	entries, err := os.ReadDir(tmpDirAbs)
573→	if err != nil {
574→		return "", false
575→	}
576→
577→	var latestFile string
578→	var latestTime time.Time
579→
580→	for _, entry := range entries {
581→		if entry.IsDir() {
582→			continue
583→		}
584→		name := entry.Name()
585→		if !strings.HasPrefix(name, preTaskFilePrefix) || !strings.HasSuffix(name, ".json") {
586→			continue
587→		}
588→
589→		// Check modification time for nested subagent handling
590→		info, err := entry.Info()
591→		if err != nil {
592→			continue
593→		}
594→		if latestFile == "" || info.ModTime().After(latestTime) {
595→			latestFile = name
596→			latestTime = info.ModTime()
597→		}
598→	}
599→
600→	if latestFile == "" {
601→		return "", false
602→	}
603→
604→	// Extract tool_use_id from filename: pre-task-<tool_use_id>.json
605→	toolUseID := strings.TrimPrefix(latestFile, preTaskFilePrefix)
606→	toolUseID = strings.TrimSuffix(toolUseID, ".json")
607→	return toolUseID, true
608→}
