620→	if err != nil {
621→		// Directory doesn't exist or can't be read - start at 1
622→		return 1
623→	}
624→
625→	// Count JSON files (checkpoints)
626→	count := 0
627→	for _, entry := range entries {
628→		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") {
629→			count++
630→		}
631→	}
632→
633→	return count + 1
634→}
